import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.DdtnLau3.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Piwork","text":"可分享、可运行的 AI 工作空间","tagline":"由可演进的 Harness 驱动。","image":{"src":"/logo.png","alt":"Piwork"},"actions":[{"theme":"brand","text":"开始使用","link":"/zh/guide/quick-start"},{"theme":"alt","text":"GitHub","link":"https://github.com/pphboy/piwork"},{"theme":"alt","text":"讨论社区","link":"https://github.com/pphboy/piwork/discussions"}]}},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),i={name:"zh/index.md"};function n(h,t,s,d,p,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="piwork-是什么" tabindex="-1">Piwork 是什么？ <a class="header-anchor" href="#piwork-是什么" aria-label="Permalink to &quot;Piwork 是什么？&quot;">​</a></h2><p>Piwork 将可运行的 AI 工作空间封装成一个可携带的单元，称为 <strong>Work</strong>。应用、文件、对话历史和执行环境保存在一起；导出后，可以在另一个 Piwork 实例中继续使用。</p><table tabindex="0"><thead><tr><th>概念</th><th>职责</th></tr></thead><tbody><tr><td><a href="/piwork/zh/concepts/work.html">Work</a></td><td><strong>工作空间。</strong> 保存环境和持久状态。</td></tr><tr><td><a href="/piwork/zh/concepts/service.html">Service</a></td><td><strong>能力。</strong> 运行应用、API 或其他容器服务。</td></tr><tr><td><a href="/piwork/zh/concepts/harness.html">Harness</a></td><td><strong>智能层。</strong> 通过模型、工具和工作空间专属指令理解并操作 Work。</td></tr></tbody></table><p>Harness 可以帮助构建和修改它所在的工作空间。它的指令、Skills、扩展包和经过验证的经验，可以随着 Work 一起演进。</p><p>默认 Web 开发使用可复用的 FastAPI + React + TypeScript + Vite 环境。标准模板自动采用已部署的更新；使用与维护入口见 <a href="/piwork/zh/guide/web-development.html">Web 开发</a>。</p><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><p><strong>创建 → 运行 → 演进 → 导出 → 分享 → 导入 → 继续</strong></p><p>将已停止的 Work 导出为 <code>.work</code> 文件，在兼容的实例中导入，再手动启动。接收方需要配置自己的模型凭据。</p><h2 id="演示-kanban-work" tabindex="-1">演示：Kanban Work <a class="header-anchor" href="#演示-kanban-work" aria-label="Permalink to &quot;演示：Kanban Work&quot;">​</a></h2><p>看板、数据、应用 Service 和帮助构建及操作看板的 Harness，共同组成一个工作空间。<a href="/piwork/zh/demo/kanban.html">查看 Kanban 演示说明</a>。可下载的演示包和录屏仍在准备中。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p><a href="/piwork/zh/guide/quick-start.html">在终端试用 Core 和 CLI</a>：使用已有初始化环境，Core 和 CLI 各一条 Docker 命令，Core 也可单独下载 <a href="/piwork/piwork/install/0.0.2-fb4f577da3b4-512ec778b267/docker-compose.yml">docker-compose.yml</a>。登录、创建 Work 后即可收到首条回复。Piwork 0.0.2 Preview 镜像已发布并完成匿名核验。</p><p>原生 CLI 保留为 Quick Start 的折叠替代入口。高级 Core-only Demo 见 <a href="/piwork/zh/guide/installation.html#core-compose-demo">安装说明</a>。</p>',13)])])}const m=e(i,[["render",n]]);export{c as __pageData,m as default};
